:root {
  /* Colors */
  --color-fog-canvas: #fafafa;
  --color-paper-surface: #ffffff;
  --color-jet-ink: #171717;
  --color-graphite-text: #4d4d4d;
  --color-pewter-icon: #8f8f8f;
  --color-mist-border: #ebebeb;
  --color-ash-ring: #00000014;
  --color-cobalt-signal: #0070f3;

  /* Typography — Font Families */
  --font-geist-sans: "Geist", "GeistSans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-geist-mono: "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.82;
  --tracking-small: 0.2px;
  --text-caption: 12px;
  --leading-caption: 1.67;
  --tracking-caption: 0px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.38;
  --tracking-body-sm: 0px;
  --text-body: 14px;
  --leading-body: 1.43;
  --tracking-body: 0px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: -0.32px;
  --text-subheading: 24px;
  --leading-subheading: 1.33;
  --tracking-subheading: -0.96px;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1.1;
  --tracking-heading-sm: -1.2px;
  --text-heading: 40px;
  --leading-heading: 1.0;
  --tracking-heading: -2.4px;
  --text-heading-lg: 56px;
  --leading-heading-lg: 1.0;
  --tracking-heading-lg: -3.36px;
  --text-display: 64px;
  --leading-display: 1.0;
  --tracking-display: -3.84px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-book: 450; /* signature display and story weight */
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-44: 44px;
  --spacing-80: 80px;
  --spacing-208: 208px;
  --spacing-256: 256px;

  /* Layout */
  --layout-max-width: 1448px;
  --layout-section-gap: 208px;
  --layout-card-padding: 24px;
  --layout-element-gap: 12px;
  --layout-nav-height: 64px;

  /* Border Radius */
  --radius-none: 0px;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 20px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-tags: 9999px;
  --radius-nav: 6px;
  --radius-cards: 6px;
  --radius-inner-tiles: 8px;
  --radius-small-elements: 4px;
  --radius-sections: 20px;
  --radius-images: 0px;

  /* Shadows */
  --shadow-subtle: 0 0 0 1px #ebebeb;
  --shadow-subtle-2: 0 0 0 1px rgba(0, 0, 0, 0.08);
  --shadow-sm: 0 0 0 1px rgba(0, 0, 0, 0.08), 0 2px 2px 0 rgba(0, 0, 0, 0.04), 0 0 0 1px #fafafa;
  --shadow-sm-2: inset 0 1px 2px 0 rgba(0, 0, 0, 0.18), inset 0 0 24px 0 rgba(0, 0, 0, 0.14);

  /* Surfaces */
  --surface-fog-canvas: #fafafa;
  --surface-paper-surface: #ffffff;
  --surface-jet-ink: #171717;
}

